     1	"use server";
     2	
     3	/**
     4	 * Creates an issue after the per-project quota check.
     5	 *
     6	 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
     7	 * here — the plan of the owning organization decides `issuesPerProject`.
     8	 *
     9	 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
    10	 * getActor, toActionResult
    11	 */
    12	
    13	import { withAction } from "@/actions/_lib/with-action";
    14	import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
    15	import { getPlanLimits } from "@/config/plan-limits";
    16	import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
    17	import { can } from "@/lib/permissions";
    18	import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
    19	import { createIssue, listIssues } from "@/server/services/issue-service";
    20	import { getOrganizationSummary } from "@/server/services/organization-service";
    21	import type { ActionResult } from "@/types/api";
    22	import type { Issue } from "@/types/issue";
    23	import type { Actor } from "@/types/member";
    24	
    25	const run = withAction<typeof createIssueSchema, Issue>(
    26	  createIssueSchema,
    27	  async (raw, actor) => {
    28	    const input = raw as CreateIssueInput;
    29	
    30	    const allowed = can(actor, "issue:create", {
    31	      kind: "issue",
    32	      orgId: input.orgId,
    33	      projectId: input.projectId,
    34	      issueId: "" as Issue["id"],
    35	      authorId: actor.userId,
    36	      assigneeId: input.assigneeId,
    37	    });
    38	    if (!allowed) {
    39	      throw new ForbiddenActionError("issue:create");
    40	    }
    41	
    42	    await assertProjectHasRoom(actor, input);
    43	
    44	    const issue = await createIssue(actor, input);
    45	
    46	    revalidateTagged(
    47	      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
    48	      CACHE_PROFILES.minutes,
    49	    );
    50	    return issue;
    51	  },
    52	  { revalidate: ["issues"], cacheProfile: "minutes" },
    53	);
    54	
    55	/**
    56	 * Counts the issues already living in the project and compares them with the
    57	 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
    58	 * which is why the count deliberately includes them.
    59	 */
    60	async function assertProjectHasRoom(
    61	  actor: Actor,
    62	  input: CreateIssueInput,
    63	): Promise<void> {
    64	  const summary = await getOrganizationSummary(actor, input.orgId);
    65	  const limits = getPlanLimits(summary.organization.plan);
    66	
    67	  const existing = await listIssues(actor, {
    68	    orgId: input.orgId,
    69	    projectId: input.projectId,
    70	    limit: 1,
    71	    includeArchived: true,
    72	  });
    73	
    74	  if (existing.total >= limits.issuesPerProject) {
    75	    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
    76	  }
    77	}
    78	
    79	export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
    80	  return run(raw);
    81	}
=== new page
     1	/**
     2	 * New issue page; blocked at the per-project issue quota.
     3	 *
     4	 * Owner D. `issuesPerProject` counts archived issues too, so an org that has
     5	 * filled a project cannot make room by archiving — that is deliberate, and the
     6	 * copy below says so rather than leaving people to guess.
     7	 *
     8	 * Must call (do not reimplement): can, getPlanLimits
     9	 */
    10	
    11	import Link from "next/link";
    12	import { notFound } from "next/navigation";
    13	import type { Metadata } from "next";
    14	import { createIssueAction } from "@/actions/issues/create-issue";
    15	import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
    16	import { IssueForm } from "@/components/domain/issue/issue-form";
    17	import { getPlanLimits } from "@/config/plan-limits";
    18	import { can } from "@/lib/permissions";
    19	import { issueStatusSchema } from "@/schemas/issue";
    20	import { listIssues } from "@/server/services/issue-service";
    21	import { listLabels } from "@/server/services/label-service";
    22	import { listMembers } from "@/server/services/member-service";
    23	import type { IssueStatus } from "@/types/issue";
    24	import { loadProjectContext } from "../../../../_lib/project-context";
    25	
    26	type PageParams = { orgSlug: string; projectSlug: string };
    27	
    28	export const dynamic = "force-dynamic";
    29	
    30	export const metadata: Metadata = {
    31	  title: "New issue",
    32	};
    33	
    34	const MEMBER_PICKER_LIMIT = 100;
    35	
    36	export default async function Page(props: {
    37	  params: Promise<PageParams>;
    38	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    39	}) {
    40	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    41	  const { orgSlug, projectSlug } = await props.params;
    42	  await props.searchParams;
    43	
    44	  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);
    45	
    46	  const allowed = can(actor, "issue:create", {
    47	    kind: "issue",
    48	    orgId: org.id,
    49	    projectId: project.id,
    50	    issueId: PENDING_ISSUE_ID,
    51	    authorId: actor.userId,
    52	    assigneeId: null,
    53	  });
    54	  if (!allowed) {
    55	    notFound();
    56	  }
    57	
    58	  const limits = getPlanLimits(org.plan);
    59	  const existing = await listIssues(actor, {
    60	    orgId: org.id,
    61	    projectId: project.id,
    62	    limit: 1,
    63	    includeArchived: true,
    64	  });
    65	
    66	  if (existing.total >= limits.issuesPerProject) {
    67	    return (
    68	      <div className="max-w-lg space-y-4">
    69	        <h1 className="text-xl font-semibold tracking-tight">
    70	          This project is full
    71	        </h1>
    72	        <p className="text-sm text-slate-600">
    73	          The {org.plan} plan allows {limits.issuesPerProject} issues per
    74	          project, archived ones included, and {existing.total} exist. Upgrading
    75	          raises the ceiling; a new project starts with a fresh one.
    76	        </p>
    77	        <div className="flex gap-4 text-sm">
    78	          <Link
    79	            href={`/${orgSlug}/projects/${projectSlug}/issues`}
    80	            className="text-slate-600"
    81	          >
    82	            Back to issues
    83	          </Link>
    84	          <Link href={`/${orgSlug}/settings/billing`} className="text-indigo-600">
    85	            See plans
    86	          </Link>
    87	        </div>
    88	      </div>
    89	    );
    90	  }
    91	
    92	  const [members, labels] = await Promise.all([
    93	    listMembers(actor, { orgId: org.id, limit: MEMBER_PICKER_LIMIT }),
    94	    listLabels(actor, org.id),
    95	  ]);
    96	
    97	  return (
    98	    <div className="max-w-2xl space-y-8">
    99	      <header>
   100	        <h1 className="text-2xl font-semibold tracking-tight">New issue</h1>
   101	        <p className="mt-1 text-sm text-slate-600">
   102	          In {project.name} · {existing.total} of {limits.issuesPerProject} used
   103	        </p>
   104	      </header>
   105	
   106	      <IssueForm
   107	        orgId={org.id}
   108	        projectId={project.id}
   109	        members={members.items}
   110	        labels={labels}
   111	        defaultValues={{
   112	          orgId: org.id,
   113	          projectId: project.id,
   114	          status: defaultStatusFor(org.settings.defaultIssueStatus),
   115	        }}
   116	        onSubmit={createIssueAction}
   117	      />
   118	    </div>
   119	  );
   120	}
   121	
   122	/**
   123	 * `OrganizationSettings.defaultIssueStatus` is stored as a plain string, so it
   124	 * is re-validated against the enum before it seeds the form.
   125	 */
   126	function defaultStatusFor(stored: string): IssueStatus {
   127	  const parsed = issueStatusSchema.safeParse(stored);
   128	  return parsed.success ? parsed.data : "backlog";
   129	}

