     1	import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
     2	import { toIsoTimestamp } from "@/types/common";
     3	
     4	/**
     5	 * Soft-delete conventions.
     6	 *
     7	 * Issues, projects and comments are never physically removed — they get an
     8	 * `archived_at` timestamp. Repositories must express "live rows only" through
     9	 * these helpers so the predicate stays in one place; a raw
    10	 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
    11	 * drift this module prevents.
    12	 */
    13	
    14	export function isArchived(row: SoftDeletable): boolean {
    15	  return row.archivedAt !== null;
    16	}
    17	
    18	export function isLive(row: SoftDeletable): boolean {
    19	  return row.archivedAt === null;
    20	}
    21	
    22	/** Filters an in-memory collection according to an `ArchiveScope`. */
    23	export function applyArchiveScope<T extends SoftDeletable>(
    24	  rows: readonly T[],
    25	  scope: ArchiveScope = {},
    26	): readonly T[] {
    27	  return scope.includeArchived === true ? rows : rows.filter(isLive);
    28	}
    29	
    30	/** True when the repository should add the `archived_at IS NULL` predicate. */
    31	export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
    32	  return scope.includeArchived !== true;
    33	}
    34	
    35	/** The column patch that archives a row. */
    36	export function archivePatch(now: Date = new Date()): {
    37	  archivedAt: IsoTimestamp;
    38	  updatedAt: IsoTimestamp;
    39	} {
    40	  const stamp = toIsoTimestamp(now);
    41	  return { archivedAt: stamp, updatedAt: stamp };
    42	}
    43	
    44	/** The column patch that restores an archived row. */
    45	export function restorePatch(now: Date = new Date()): {
    46	  archivedAt: null;
    47	  updatedAt: IsoTimestamp;
    48	} {
    49	  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
    50	}
    51	
    52	export class AlreadyArchivedError extends Error {
    53	  readonly code = "conflict" as const;
    54	
    55	  constructor(readonly entity: string, readonly id: string) {
    56	    super(`${entity} ${id} is already archived.`);
    57	    this.name = "AlreadyArchivedError";
    58	  }
    59	}
    60	
    61	/** Guard for archive actions, so double-archiving is a domain-level conflict. */
    62	export function assertNotArchived(
    63	  entity: string,
    64	  id: string,
    65	  row: SoftDeletable,
    66	): void {
    67	  if (isArchived(row)) {
    68	    throw new AlreadyArchivedError(entity, id);
    69	  }
    70	}

