     1	import { mkdirSync } from "node:fs";
     2	import { dirname, resolve } from "node:path";
     3	import Database from "better-sqlite3";
     4	import { drizzle } from "drizzle-orm/better-sqlite3";
     5	import * as schema from "./schema";
     6	
     7	/**
     8	 * The single Drizzle connection for the process.
     9	 *
    10	 * Repositories import `db` from `@/server/db` (the barrel), never this module
    11	 * directly, so the connection can be swapped in tests. Never construct a
    12	 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
    13	 * event bus assumes one writer.
    14	 */
    15	
    16	const DEFAULT_DB_PATH = "./data/taskflow.db";
    17	
    18	let instance: ReturnType<typeof createClient> | null = null;
    19	
    20	function createClient(path: string) {
    21	  const absolute = resolve(process.cwd(), path);
    22	  mkdirSync(dirname(absolute), { recursive: true });
    23	  const sqlite = new Database(absolute);
    24	  sqlite.pragma("journal_mode = WAL");
    25	  sqlite.pragma("foreign_keys = ON");
    26	  return drizzle(sqlite, { schema });
    27	}
    28	
    29	export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
    30	  instance ??= createClient(path);
    31	  return instance;
    32	}
    33	
    34	/** Test hook: point the singleton at an in-memory database. */
    35	export function useInMemoryDb(): void {
    36	  instance = createClient(":memory:");
    37	}
    38	
    39	export type Db = ReturnType<typeof getDb>;
    40	export type DbSchema = typeof schema;

