     1	/**
     2	 * Maps thrown domain errors onto `AppErrorShape`.
     3	 *
     4	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
     5	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
     6	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
     7	 * client. Everything funnels through `toAppError()` so one thrown class maps
     8	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
     9	 */
    10	import { FeatureDisabledError } from "@/lib/feature-flags";
    11	import { PermissionDeniedError } from "@/lib/permissions";
    12	import { InvalidSlugError } from "@/lib/slug";
    13	import { AlreadyArchivedError } from "@/lib/soft-delete";
    14	import { TenantScopeError } from "@/lib/tenant";
    15	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
    16	import { ZodError, type ZodIssue } from "zod";
    17	
    18	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
    19	  unauthorized: 401,
    20	  forbidden: 403,
    21	  not_found: 404,
    22	  validation_failed: 422,
    23	  conflict: 409,
    24	  rate_limited: 429,
    25	  plan_limit_exceeded: 402,
    26	  tenant_scope_violation: 403,
    27	  internal_error: 500,
    28	};
    29	
    30	/** True for the error classes this module knows how to translate faithfully. */
    31	export function isDomainError(error: unknown): boolean {
    32	  return (
    33	    error instanceof PermissionDeniedError ||
    34	    error instanceof TenantScopeError ||
    35	    error instanceof FeatureDisabledError ||
    36	    error instanceof AlreadyArchivedError ||
    37	    error instanceof InvalidSlugError ||
    38	    error instanceof ZodError
    39	  );
    40	}
    41	
    42	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
    43	export function fieldErrorsFromZod(
    44	  error: ZodError,
    45	): Readonly<Record<string, readonly string[]>> {
    46	  const fields: Record<string, string[]> = {};
    47	  for (const issue of error.issues as readonly ZodIssue[]) {
    48	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    49	    (fields[key] ??= []).push(issue.message);
    50	  }
    51	  return fields;
    52	}
    53	
    54	export function toAppError(error: unknown): AppErrorShape {
    55	  if (error instanceof ZodError) {
    56	    return {
    57	      code: "validation_failed",
    58	      message: "Please correct the highlighted fields.",
    59	      fieldErrors: fieldErrorsFromZod(error),
    60	    };
    61	  }
    62	
    63	  if (error instanceof PermissionDeniedError) {
    64	    return {
    65	      code: "forbidden",
    66	      message: error.message,
    67	      meta: {
    68	        action: error.action,
    69	        resourceKind: error.decision.resourceKind,
    70	        reason: error.decision.reason,
    71	      },
    72	    };
    73	  }
    74	
    75	  if (error instanceof TenantScopeError) {
    76	    return {
    77	      code: "tenant_scope_violation",
    78	      message: "That resource belongs to a different organization.",
    79	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    80	    };
    81	  }
    82	
    83	  if (error instanceof FeatureDisabledError) {
    84	    return {
    85	      code: "forbidden",
    86	      message: error.message,
    87	      meta: { flag: error.flag },
    88	    };
    89	  }
    90	
    91	  if (error instanceof AlreadyArchivedError) {
    92	    return {
    93	      code: "conflict",
    94	      message: error.message,
    95	      meta: { entity: error.entity, id: error.id },
    96	    };
    97	  }
    98	
    99	  if (error instanceof InvalidSlugError) {
   100	    return {
   101	      code: "validation_failed",
   102	      message: error.message,
   103	      fieldErrors: { slug: [error.message] },
   104	      meta: { value: error.value },
   105	    };
   106	  }
   107	
   108	  return {
   109	    code: "internal_error",
   110	    message:
   111	      error instanceof Error ? error.message : "Something went wrong. Try again.",
   112	  };
   113	}
   114	
   115	/** The failure envelope a Server Action returns instead of throwing. */
   116	export function toActionResult(error: unknown): ActionResult<never> {
   117	  return {
   118	    ok: false,
   119	    error: toAppError(error),
   120	    submittedAt: new Date().toISOString(),
   121	  };
   122	}
