     1	/**
     2	 * Cache tag vocabulary and revalidation helpers.
     3	 *
     4	 * Next 16 requires a cache-life profile as the second argument to
     5	 * `revalidateTag`, which is exactly the kind of API change that rots when it
     6	 * is spelled out at forty call sites. Server Actions call
     7	 * `revalidateTagged([...])` and never import `next/cache` themselves.
     8	 */
     9	import { revalidateTag } from "next/cache";
    10	import type { IssueId, OrgId, ProjectId } from "@/types/common";
    11	
    12	/** The cache-life profiles this app uses, by how stale a read may be. */
    13	export const CACHE_PROFILES: Readonly<
    14	  Record<"seconds" | "minutes" | "hours", string>
    15	> = {
    16	  seconds: "seconds",
    17	  minutes: "minutes",
    18	  hours: "hours",
    19	};
    20	
    21	export function orgTag(orgId: OrgId): string {
    22	  return `org:${orgId}`;
    23	}
    24	
    25	export function projectTag(projectId: ProjectId): string {
    26	  return `project:${projectId}`;
    27	}
    28	
    29	export function issueTag(issueId: IssueId): string {
    30	  return `issue:${issueId}`;
    31	}
    32	
    33	/**
    34	 * Invalidates every supplied tag under one profile, de-duplicating first so a
    35	 * caller can splice together tag lists without worrying about repeats.
    36	 */
    37	export function revalidateTagged(
    38	  tags: readonly string[],
    39	  profile: string = CACHE_PROFILES.minutes,
    40	): void {
    41	  for (const tag of new Set(tags)) {
    42	    if (tag === "") continue;
    43	    revalidateTag(tag, profile);
    44	  }
    45	}

