    29	export function issueTag(issueId: IssueId): string {
    30	  return `issue:${issueId}`;
    31	}
    32	
    33	/**
    34	 * Invalidates every supplied tag under one profile, de-duplicating first so a
    35	 * caller can splice together tag lists without worrying about repeats.
    36	 */
    37	export function revalidateTagged(
    38	  tags: readonly string[],
    39	  profile: string = CACHE_PROFILES.minutes,
    40	): void {
    41	  for (const tag of new Set(tags)) {
    42	    if (tag === "") continue;
    43	    revalidateTag(tag, profile);
    44	  }
