=== project-context
     1	/**
     2	 * Tenant context plus the project named by `[projectSlug]`.
     3	 *
     4	 * Owner D. Private to the tenant subtree. Every page under
     5	 * `projects/[projectSlug]` needs the same four values, and resolving the
     6	 * project through `ProjectService` (rather than the repository) is what applies
     7	 * the visibility rules — a `private` project the caller is not on must 404,
     8	 * not merely render empty.
     9	 */
    10	
    11	import { notFound } from "next/navigation";
    12	import { getProject } from "@/server/services/project-service";
    13	import type { ProjectWithStats } from "@/types/project";
    14	import { loadTenantContext, type TenantContext } from "./tenant-context";
    15	
    16	export type ProjectContext = TenantContext & {
    17	  readonly project: ProjectWithStats["project"];
    18	  readonly stats: ProjectWithStats["stats"];
    19	};
    20	
    21	export async function loadProjectContext(
    22	  orgSlug: string,
    23	  projectSlug: string,
    24	): Promise<ProjectContext> {
    25	  const tenant = await loadTenantContext(orgSlug);
    26	
    27	  const found = await findProject(tenant, projectSlug);
    28	  if (found === null) {
    29	    notFound();
    30	  }
    31	
    32	  return { ...tenant, project: found.project, stats: found.stats };
    33	}
    34	
    35	/**
    36	 * "Does not exist" and "you may not see it" both come back as `null`, so the
    37	 * two cases are indistinguishable from outside — the same reasoning as the
    38	 * organization lookup in `tenant-context.ts`.
    39	 */
    40	async function findProject(
    41	  tenant: TenantContext,
    42	  projectSlug: string,
    43	): Promise<ProjectWithStats | null> {
    44	  try {
    45	    return await getProject(tenant.actor, tenant.org.id, projectSlug);
    46	  } catch {
    47	    return null;
    48	  }
    49	}
